/* ================= home, accounts, challenges, tutorial, demo ================= */
const lsGet=k=>{try{return JSON.parse(localStorage.getItem(k)||'null')}catch(e){return null}};
const lsSet=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v))}catch(e){}};
// accounts are shared with Barycenter (same storage key); each game keeps its own progress per account
const ACC_KEY='barycenter.accounts',PROG_KEY='biosphere.progress';
let ACC=lsGet(ACC_KEY);if(!ACC||!Array.isArray(ACC.list))ACC={list:[],cur:'guest',devicePlays:0};if(ACC.cur!=='guest'&&!ACC.list.some(a=>a.id===ACC.cur))ACC.cur='guest';
let ACCN=0;
const progKey=id=>id==='guest'?PROG_KEY:PROG_KEY+'.'+id;
const blankProg=()=>({stars:{},plays:0,secs:0});
let PROG=blankProg();
function loadProg(){const v=lsGet(progKey(ACC.cur));PROG=Object.assign(blankProg(),v&&typeof v.stars==='object'?v:{})}
function saveProg(){lsSet(progKey(ACC.cur),PROG)}
function saveAcc(){const cur=lsGet(ACC_KEY);if(cur&&Array.isArray(cur.list)){/* keep fields Barycenter added */for(const a of ACC.list){const o=cur.list.find(x=>x.id===a.id);if(o)Object.keys(o).forEach(k=>{if(!(k in a))a[k]=o[k]})}if(cur.devicePlays>ACC.devicePlays)ACC.devicePlays=cur.devicePlays}lsSet(ACC_KEY,ACC)}
const curAcc=()=>ACC.list.find(a=>a.id===ACC.cur);
const accName=()=>(curAcc()||{name:'Guest'}).name;
const pinHash=p=>{let h=5381;for(const c of 'bary:'+p)h=((h*33)^c.charCodeAt(0))>>>0;return h.toString(36)};
const GCOUNT='https://abacus.jasoncameron.dev',GPATH='barycenter-sandbox/biosphere-plays';let GLOBAL=null;
function gCount(op){try{const ctl=new AbortController();setTimeout(()=>ctl.abort(),6000);fetch(`${GCOUNT}/${op}/${GPATH}`,{signal:ctl.signal,cache:'no-store'}).then(r=>r.ok?r.json():null).then(j=>{if(j&&Number.isFinite(+j.value)){GLOBAL=Math.max(GLOBAL||0,+j.value);updateAcctUI()}}).catch(()=>{})}catch(e){}}
function countPlay(){PROG.plays++;ACC.devicePlays=(ACC.devicePlays||0)+1;saveProg();saveAcc();if(GLOBAL!=null)GLOBAL++;updateAcctUI();gCount('hit')}
function updateAcctUI(){$('hAcctName').textContent=curAcc()?accName():'Guest · make an account';$('hPlaysN').textContent=(GLOBAL!=null?GLOBAL:PROG.plays).toLocaleString();$('hPlaysL').textContent=GLOBAL!=null?'plays by everyone':'plays';$('acctBtn').title=`Account: ${accName()} (saved on this device)`}
function switchAcc(id,quiet){if(id===ACC.cur)return;saveProg();ACC.cur=id;saveAcc();loadProg();ACCN++;updateAcctUI();if(!$('home').hidden)homeView($('hChalView').hidden?'hMain':'hChalView');if(!quiet)toast(`Signed in as ${accName()}`);renderAcct()}
let acctPend=null;
function renderAcct(msg){const L=$('acctList');L.textContent='';$('acctMsg').textContent=msg||'';
  for(const a of [{id:'guest',name:'Guest',guest:1},...ACC.list]){const pr=a.id===ACC.cur?PROG:(lsGet(progKey(a.id))||{stars:{},plays:0}),cur=a.id===ACC.cur,r=document.createElement('div');r.className='arow'+(cur?' cur':'');
    const nm=document.createElement('div');nm.className='an';nm.innerHTML='<div></div><div class="as"></div>';nm.children[0].textContent=(a.pin?'🔒 ':'')+a.name+(cur?' (signed in)':'');nm.children[1].textContent=`★ ${Object.values(pr.stars||{}).reduce((x,y)=>x+y,0)} in Biosphere · ${pr.plays||0} plays`;r.appendChild(nm);
    if(!cur){if(acctPend===a.id){const inp=document.createElement('input');inp.placeholder='PIN';inp.maxLength=4;inp.className='apin';const go=document.createElement('button');go.className='btn primary';go.textContent='OK';const t=()=>{if(pinHash(inp.value)===a.pin){acctPend=null;switchAcc(a.id)}else renderAcct('Wrong PIN')};go.onclick=t;inp.onkeydown=e=>{if(e.key==='Enter')t()};r.append(inp,go);setTimeout(()=>inp.focus(),0)}
      else{const b=document.createElement('button');b.className='btn';b.textContent=a.guest?'Use guest':'Sign in';b.onclick=()=>{if(a.pin){acctPend=a.id;renderAcct()}else switchAcc(a.id)};r.appendChild(b)}}
    else if(!a.guest){const so=document.createElement('button');so.className='btn';so.textContent='Sign out';so.onclick=()=>switchAcc('guest');r.appendChild(so)}
    L.appendChild(r)}}
function openAcct(){acctPend=null;$('acct').hidden=false;renderAcct()}
$('acctForm').addEventListener('submit',e=>{e.preventDefault();const name=$('acctNew').value.trim().replace(/\s+/g,' ').slice(0,20),pin=$('acctPin').value.trim();
  if(!name)return renderAcct('Type a name first');if(/^guest$/i.test(name)||ACC.list.some(a=>a.name.toLowerCase()===name.toLowerCase()))return renderAcct('That name is taken on this device');if(pin&&!/^\d{4}$/.test(pin))return renderAcct('A PIN is 4 digits (or leave it empty)');
  const fromGuest=ACC.cur==='guest'&&(PROG.plays||Object.keys(PROG.stars).length);const a={id:'a'+Date.now().toString(36)+Math.floor(Math.random()*1e4).toString(36),name,created:Date.now()};if(pin)a.pin=pinHash(pin);
  if(fromGuest){lsSet(progKey(a.id),PROG);lsSet(PROG_KEY,blankProg())}ACC.list.push(a);saveAcc();$('acctNew').value='';$('acctPin').value='';switchAcc(a.id,true);toast(`Account ${name} created`);renderAcct(fromGuest?'Your guest progress moved into this account.':'')});
$('hAcctBtn').onclick=openAcct;$('acctBtn').onclick=openAcct;$('acctClose').onclick=()=>$('acct').hidden=true;$('acct').addEventListener('click',e=>{if(e.target.id==='acct')$('acct').hidden=true});
$('hPlays').onclick=()=>{gCount('get');toast(GLOBAL!=null?`${GLOBAL.toLocaleString()} plays by everyone · ${PROG.plays} by you`:`${PROG.plays} plays by you on this device`)};

/* challenges */
const CH={active:null,idx:-1,events:[],hold:{},t0:0,real0:0,done:false,failed:'',loading:false,ref:{}};
function chEv(k,d){if(CH.active&&!CH.done&&!CH.loading)CH.events.push({k,...(d||{}),t:S.t})}
const cnt=sp=>{let n=0;for(const a of S.animals)if(!a.dead&&a.sp===sp)n++;return n};
const cntBorn=sp=>{let n=0;for(const a of S.animals)if(!a.dead&&a.sp===sp&&a.born>CH.t0)n++;return n};
function hold(key,cond,years){if(!cond){CH.hold[key]=null;return 0}if(CH.hold[key]==null)CH.hold[key]=S.t;return Math.min(1,(S.t-CH.hold[key])/(years*365))}
const holdTxt=(p,Y)=>p>0?`holding: ${(p*Y).toFixed(1)} of ${Y} years`:'';
const realSecs=()=>(performance.now()-CH.real0)/1000;
const byTime=(t3,t2)=>()=>{const s=realSecs();return s<=t3?3:s<=t2?2:1};
const evN=k=>CH.events.filter(e=>e.k===k).length;
const scn=(id,f)=>()=>{loadScen(id);if(f)f()};
const CHALS=[];const CC=(diff,o)=>CHALS.push({diff,...o});
const yrs=()=>(S.t-CH.t0)/365;
const snowCells=()=>{let n=0;for(let i=0;i<N;i++)if(!isWater(i)&&meanT(i)<-2)n++;return n};
// find and inspect
CC(1,{t:'Find a fox',g:'Find a fox and follow it with the camera.',hint:'Type fox in the search bar and press Enter.',setup:scn('meadow',()=>{const r=S.animals.filter(a=>a.sp==='rabbit');for(let k=0;k<6&&r.length;k++){const z=r[Math.floor(rnd()*r.length)];spawnAt('fox',z.x,z.y,2,true,0.9)}}),
  check:()=>{const ok=S.sel&&S.sel.sp==='fox';return[ok&&S.follow,ok?1:0,ok?'Found one':'Not found yet']},stars:byTime(20,45)});
CC(1.1,{t:'Lend a hand',g:'Help 3 hungry animals: select each one and press Feed.',hint:'Click an animal, then press Feed in the Inspect tab. Look for ones with low energy.',setup:()=>{loadScen('meadow');CH.ref.n=FEEDS},check:()=>{const n=FEEDS-CH.ref.n;return[n>=3,n/3,`${Math.min(n,3)} of 3 animals fed`]},stars:byTime(30,70)});
CC(1.2,{t:'Copycat',g:'Clone an animal: select one and press Clone.',hint:'Click any animal, then press Clone in the Inspect tab. The copy has exactly the same genes.',setup:()=>{loadScen('meadow');CH.ref.n=CLONES},check:()=>{const n=CLONES-CH.ref.n;return[n>=1,n?1:0,n?'Cloned!':'No clone yet']},stars:byTime(20,50)});
CC(1.3,{t:'Berry patch',g:'Plant 8 berry bushes. Bears and people eat their berries.',hint:'Pick Berries in the toolbar and click on green land.',setup:scn('meadow'),check:()=>{const n=PLACED.bush||0;return[n>=8,n/8,`${Math.min(n,8)} of 8 planted`]},stars:byTime(25,60)});
CC(1.4,{t:'New arrivals',g:'Watch 15 babies be born.',hint:'Speed up time. Rabbits and mice have the biggest families.',setup:scn('meadow'),check:()=>{const n=evN('birth');return[n>=15,n/15,`${Math.min(n,15)} of 15 births`]},stars:byTime(20,50)});
CC(1.3,{t:'Around the world',g:'Travel the camera all the way around the world, east or west, until you are back where you started.',hint:'Drag the map or hold A or D. The world wraps around like a planet.',setup:()=>{loadScen('meadow');CH.ref.x=cam.x},check:()=>{const d=Math.abs(cam.x-CH.ref.x)/(GW*CELL);return[d>=1,Math.min(1,d),`${Math.round(Math.min(1,d)*100)}% of the way round`]},stars:byTime(25,60)});
CC(1.15,{t:'Fast forward',g:'Run time at 1 year per second.',hint:'Press the “1 yr” button next to the pause button.',setup:scn('meadow'),check:()=>{const ok=!S.paused&&S.speed>=365;return[ok,ok?1:0,'']},stars:byTime(10,30)});
CC(1.5,{t:'Read the genes',g:'Select a deer and look at its genes in the Inspect tab.',hint:'Click a deer (or search for deer), then open Inspect.',setup:scn('meadow'),check:()=>{const ok=S.sel&&S.sel.sp==='deer'&&!$('pane-insp').hidden;return[ok,ok?1:0,'']},stars:byTime(25,60)});
CC(1.6,{t:'Stock the lake',g:'Release at least 12 fish into the water.',hint:'Pick Fish in the toolbar and click on a lake or the sea.',setup:scn('meadow'),check:()=>{const n=PLACED.fish||0;return[n>=12,n/12,`${n} of 12 released`]},stars:byTime(20,50)});
CC(1.7,{t:'Plant a grove',g:'Plant 15 trees of any kind.',hint:'Pick Oak or Pine and click or drag across grassland.',setup:scn('meadow'),check:()=>{const n=Object.keys(TK).reduce((s,k)=>s+(PLACED[k]||0),0);return[n>=15,n/15,`${n} of 15 planted`]},stars:byTime(25,60)});
// grow populations by breeding (only animals born during the challenge count)
[['rabbit','meadow',120,2],['mouse','meadow',150,2.4],['fish','meadow',250,2.6],['deer','meadow',40,3.4],['rabbit','meadow',300,4.2],['zebra','savanna',50,4.4],['bison','savanna',35,4.6],['wolf','meadow',12,5],['lion','savanna',12,5.4],['camel','desert',20,5.6],['bear','meadow',6,6.4],['otter','islands',14,5.2],['hawk','meadow',8,5.8],['fish','islands',500,4]].forEach(([k,sc,n,d])=>
  CC(d,{t:`${n} ${SP[k].pl.toLowerCase()} born`,g:`Grow the ${SP[k].pl.toLowerCase()}: have ${n} alive that were born during this challenge.`,hint:`They need food, water and a bearable climate. Speed up time; give them more food or fewer predators. Releasing more parents helps too.`,setup:scn(sc),
   check:()=>{const c=cntBorn(k);return[c>=n,c/n,`${c} of ${n} born and alive · ${cnt(k)} in total`]},fail:()=>cnt(k)?'':`The ${SP[k].pl.toLowerCase()} died out`,stars:byTime(n>100?60:90,n>100?150:220)}));
// coexistence of predator and prey
[['rabbit','fox','meadow',5,2.8],['deer','wolf','meadow',5,3.2],['zebra','lion','savanna',5,3.6],['fish','otter','islands',5,3],['rabbit','fox','meadow',15,5],['deer','wolf','meadow',15,5.6],['zebra','lion','savanna',15,6],['fish','otter','islands',15,5.3],['rabbit','fox','meadow',40,7.5]].forEach(([p,q,sc,Y,d])=>
  CC(d,{t:`${SP[p].pl} and ${SP[q].pl.toLowerCase()}, ${Y} years`,g:`Keep both ${SP[p].pl.toLowerCase()} and ${SP[q].pl.toLowerCase()} alive for ${Y} years in a row.`,hint:`If the hunters eat too much, the prey vanishes and then the hunters starve. Plant food, add prey, or remove a few hunters to keep the balance.`,setup:scn(sc),
   check:()=>{const a=cnt(p),b=cnt(q),pr=hold('c',a>0&&b>0,Y);return[pr>=1,pr,`${a} ${SP[p].pl.toLowerCase()} · ${b} ${SP[q].pl.toLowerCase()} · ${holdTxt(pr,Y)}`]},fail:()=>!cnt(p)?`The ${SP[p].pl.toLowerCase()} died out`:!cnt(q)?`The ${SP[q].pl.toLowerCase()} died out`:'',stars:byTime(Y*8,Y*20)}));
// evolution
[['rabbit','fur',6,'meadow',-9,4.6],['rabbit','fur',12,'meadow',-12,6.6],['deer','fur',8,'meadow',-11,5.8],['rabbit','speed',1.12,'meadow',0,5],['rabbit','speed',1.25,'meadow',0,7],['deer','sense',1.12,'meadow',0,6.2],['bison','size',1.12,'arctic',0,6.8],['fish','speed',1.15,'islands',0,6]].forEach(([k,g,v,sc,T,d])=>
  CC(d,{t:`Evolve ${g==='fur'?'thicker fur':g==='speed'?'faster':g==='sense'?'sharper senses':'bigger'} ${SP[k].pl.toLowerCase()}${v>1.2||v>=12?' II':''}`,g:`Through natural selection, raise the average ${g==='fur'?'cold tolerance (fur)':g} of the ${SP[k].pl.toLowerCase()} to ${g==='fur'?v+' °C':v.toFixed(2)}. Editing genes by hand does not count.`,
   hint:g==='fur'?'It is cold: animals with thicker fur survive and pass it on. Keep them fed and let generations pass at high speed.':g==='speed'?'Hunters catch the slowest. Keep enough hunters around (but not too many) and let time run.':g==='sense'?'Wolves catch the deer that notice them too late. Keep wolves around and let time run.':'In the cold, bigger bodies keep warm. Keep them alive and let time run.',
   setup:()=>{loadScen(sc);if(T){CL.temp=T;syncClimateUI()}if(k==='bison'){const p=randomCell(i=>habitatOK('bison',i)&&meanT(i)>-25);if(p)spawnAt('bison',p[0],p[1],24,false)}CH.ref.ge=GENEDIT},
   check:()=>{const a=avgGene(k,g),ok=a>=v&&GENEDIT===CH.ref.ge;const base=g==='fur'?0:1;return[ok,clamp((a-base)/(v-base),0,1),isNaN(a)?'None left':`Average ${g}: ${g==='fur'?a.toFixed(1)+' °C':a.toFixed(3)} · ${cnt(k)} alive${GENEDIT!==CH.ref.ge?' · gene edits do not count':''}`]},
   fail:()=>cnt(k)?'':`The ${SP[k].pl.toLowerCase()} died out`,stars:byTime(90,240)}));
[[15,4],[30,5.5],[60,7]].forEach(([n,d])=>CC(d,{t:`Generation ${n}`,g:`Breed any species to generation ${n}.`,hint:'Small animals like mice and rabbits breed fastest. Speed up time and keep them fed.',setup:scn('meadow'),check:()=>{const m=Math.max(0,...Object.values(S.maxGen));return[m>=n,m/n,`Highest generation: ${m}`]},stars:byTime(n*3,n*8)}));
// plants and land
[[.3,3],[.55,4.4],[.8,6]].forEach(([f,d])=>CC(d,{t:`Green ${Math.round(f*100)}% of the land`,g:`Bring the barren land to life: cover ${Math.round(f*100)}% of it with plants.`,hint:'Paint grass with the Grass brush; it spreads by itself where it is warm and wet. Rain and the climate sliders help.',setup:scn('barren'),check:()=>{const v=vegCover();return[v>=f,v/f,`${Math.round(v*100)}% covered`]},stars:byTime(f*120,f*300)}));
CC(4.8,{t:'Desert bloom',g:'Green the desert: raise its plant cover by 25 percentage points.',hint:'Raise the rainfall, use the Rain brush, dig lakes, or cool the climate a little.',setup:scn('desert',()=>{CH.ref.v0=vegCover()}),check:()=>{const v=vegCover(),goal=Math.min(.95,CH.ref.v0+.25);return[v>=goal,(v-CH.ref.v0)/(goal-CH.ref.v0),`${Math.round(v*100)}% covered · goal ${Math.round(goal*100)}%`]},stars:byTime(40,120)});
CC(4,{t:'Arctic thaw',g:'Warm the Arctic until its plant cover rises by 30 percentage points.',hint:'Use the Global temperature slider in the World tab.',setup:scn('arctic',()=>{CH.ref.v0=vegCover()}),check:()=>{const v=vegCover(),goal=Math.min(.95,CH.ref.v0+.3);return[v>=goal,(v-CH.ref.v0)/(goal-CH.ref.v0),`${Math.round(v*100)}% covered · goal ${Math.round(goal*100)}%`]},stars:byTime(30,90)});
[[400,3.4],[1200,5.2]].forEach(([n,d])=>CC(d,{t:`Grow ${n} more trees`,g:`Have ${n} more trees growing in the meadow than at the start.`,hint:'Plant trees in suitable places; grown trees drop saplings that grow into new trees. Fires, browsing animals and bad climate kill them.',setup:scn('meadow',()=>{CH.ref.t0=S.trees.length}),check:()=>{const c=S.trees.length-CH.ref.t0;return[c>=n,Math.max(0,c)/n,`${Math.max(0,c)} of ${n} new trees`]},stars:byTime(n/6,n/2)}));
CC(3,{t:'Dig a lake',g:'Make a new lake of at least 150 squares with the Water tool, then put 20 fish in the world.',hint:'Pick Water and paint on dry land. Then release fish into it.',setup:scn('savanna'),check:()=>{const w=Math.min(1,WATERED/150),f=cnt('fish');return[WATERED>=150&&f>=20,w*.6+Math.min(.4,f/50),`${Math.min(WATERED,150)} of 150 squares · ${f} fish`]},stars:byTime(60,150)});
CC(3.8,{t:'Snow on the mountain',g:'Raise a new mountain on the warm islands high enough to have snow all year (25 new snowy squares).',hint:'Pick Raise and paint the same spot again and again. It gets colder 6.5 °C for every kilometre up.',setup:scn('islands',()=>{CH.ref.c0=snowCells()}),check:()=>{const c=snowCells()-CH.ref.c0;return[c>=25,clamp(c/25,0,1),`New snowy squares: ${Math.max(0,c)} of 25`]},stars:byTime(40,100)});
// events
CC(4.2,{t:'Survive the ice age',g:'It is 10 °C colder. Keep at least 15 deer alive for 5 years.',hint:'Animals with thick fur survive and pass it on. Food is scarce: keep wolves in check.',setup:scn('meadow',()=>{CL.temp=-10;syncClimateUI()}),check:()=>{const n=cnt('deer'),p=hold('h',n>=15,5);return[p>=1,p,`${n} deer · ${holdTxt(p,5)}`]},fail:()=>cnt('deer')?'':'The deer died out',stars:byTime(45,120)});
CC(4.6,{t:'Heat wave',g:'It is 8 °C hotter. Keep 30 rabbits alive for 5 years.',hint:'Water and shade matter. Thin-furred rabbits cope with heat best.',setup:scn('meadow',()=>{CL.temp=8;syncClimateUI()}),check:()=>{const n=cnt('rabbit'),p=hold('h',n>=30,5);return[p>=1,p,`${n} rabbits · ${holdTxt(p,5)}`]},fail:()=>cnt('rabbit')?'':'The rabbits died out',stars:byTime(45,120)});
CC(5,{t:'Drought',g:'Rain falls to 30%. Keep 20 zebras alive for 3 years.',hint:'Use the Rain brush near the waterholes to grow grass, or dig more lakes.',setup:scn('savanna',()=>{CL.rain=.3;syncClimateUI()}),check:()=>{const n=cnt('zebra'),p=hold('h',n>=20,3);return[p>=1,p,`${n} zebras · ${holdTxt(p,3)}`]},fail:()=>cnt('zebra')?'':'The zebras died out',stars:byTime(45,120)});
CC(4.4,{t:'Stop the plague',g:'A disease spreads through the rabbits. Have 60 rabbits alive after 2 years.',hint:'Sick animals infect their neighbours. Spread healthy rabbits out, or remove the sick ones (they glow green).',setup:scn('meadow',()=>{for(const a of S.animals)if(a.sp==='rabbit'&&rnd()<.5)a.sick=rr(15,35)}),check:()=>{const n=cnt('rabbit'),y=yrs();return[y>=2&&n>=60,Math.min(1,y/2)*.6+Math.min(.4,n/150),`${n} rabbits · year ${y.toFixed(1)} of 2`]},fail:()=>cnt('rabbit')?'':'The rabbits died out',stars:byTime(40,100)});
CC(5.2,{t:'Firefighter',g:'A wildfire breaks out. Keep at least 70% of the trees alive for a year.',hint:'Pause, then paint water or remove dry grass in a line ahead of the flames to make firebreaks.',setup:scn('meadow',()=>{CH.ref.t0=S.trees.length;for(let k=0;k<5;k++){const p=randomCell(i=>!isWater(i)&&veg[i]>.5);if(p)ignite(idx(p[0],p[1]))}}),check:()=>{const f=S.trees.length/(CH.ref.t0||1),y=yrs();return[y>=1&&f>=.7,Math.min(1,y),`${Math.round(f*100)}% of trees left · ${(y*12).toFixed(0)} of 12 months`]},fail:()=>S.trees.length<CH.ref.t0*.7?'Too many trees burned':'',stars:byTime(40,100)});
CC(6,{t:'After the meteor',g:'A meteor strikes. Have 6 species alive 4 years later.',hint:'The dust cools the world for a few years. Keep the survivors fed; you can release new animals too.',setup:scn('pangaea',()=>{meteor(GW*.5,GH*.5,14)}),check:()=>{const n=speciesAlive().length,y=yrs();return[y>=4&&n>=6,Math.min(1,y/4)*.7+Math.min(.3,n/20),`${n} species · year ${y.toFixed(1)} of 4`]},stars:byTime(60,150)});
CC(5.6,{t:'Rising seas',g:'The seas rise 60 m. Keep 5 land species alive for 3 years.',hint:'Raise land for the animals, or move them to the hills.',setup:scn('meadow',()=>{CL.seaM=60;syncClimateUI();terrainChanged()}),check:()=>{const n=speciesAlive().filter(k=>SP[k].hab==='land').length,p=hold('h',n>=5,3);return[p>=1,p,`${n} land species · ${holdTxt(p,3)}`]},stars:byTime(45,120)});
CC(3.3,{t:'Call it off',g:'Start an ice age, then stop it again.',hint:'In the World tab, press ❄ Ice age, then press the same button (■ Stop ice age).',setup:scn('meadow'),check:()=>{const s=evN('event')>0,st=CH.events.some(e=>e.k==='stop'&&e.ev==='ice');return[st,st?1:s?.5:0,st?'Stopped':s?'Now stop it':'Start an ice age first']},stars:byTime(15,40)});
CC(4.5,{t:'Emergency response',g:'A wildfire and a plague break out at once. Stop both, then keep 100 rabbits alive for a year.',hint:'Press 🔥 Wildfire and 🦠 Plague in the World tab (they show ■ Stop while running) to stop them.',setup:scn('meadow',()=>{for(let k=0;k<5;k++){const p=randomCell(i=>!isWater(i)&&veg[i]>.5);if(p)ignite(idx(p[0],p[1]))}plague('rabbit')}),
  check:()=>{const fire=S.burning.size>0,sick=S.animals.some(a=>a.sick>0),calm=!fire&&!sick,n=cnt('rabbit'),p=hold('e',calm&&n>=100,1);return[p>=1,calm?0.3+0.7*p:0,calm?`${n} rabbits · ${holdTxt(p,1)}`:[fire?'Fire still burning':'',sick?'Plague still spreading':''].filter(Boolean).join(' · ')]},fail:()=>cnt('rabbit')?'':'The rabbits died out',stars:byTime(40,100)});
