CC(4.7,{t:'Jurassic balance',g:'Keep a T. rex and at least 6 triceratops alive together for 5 years.',hint:'The T. rex eats a lot. Release more plant-eaters, or give the triceratops more room.',setup:scn('jurassic'),check:()=>{const t=cnt('x_t_rex'),r=cnt('x_triceratops'),p=hold('j',t>=1&&r>=6,5);return[p>=1,p,`${t} T. rex · ${r} triceratops · ${holdTxt(p,5)}`]},fail:()=>!cnt('x_t_rex')?'The T. rex died':!cnt('x_triceratops')?'The triceratops died out':'',stars:byTime(45,120)});
