CC(2.3,{t:'Circle of life',g:'Watch 40 animals be born and 10 die of old age.',hint:'Speed up time. Small animals like mice breed and age fastest.',setup:scn('meadow'),check:()=>{const b=evN('birth'),o=CH.events.filter(e=>e.k==='death'&&e.cause==='old age').length;return[b>=40&&o>=10,Math.min(1,b/40)*.5+Math.min(1,o/10)*.5,`${Math.min(b,40)} of 40 births · ${Math.min(o,10)} of 10 old-age deaths`]},stars:byTime(30,90)});
