CC(4.3,{t:'Snow coats',g:'In a snowy Arctic, evolve the rabbits until 35% of them have white coats. Editing genes does not count.',hint:'White is recessive: a rabbit needs two w copies. In the snow, white rabbits hide from foxes and wolves, so they survive to pass it on. Keep the foxes alive (they hunt the rabbits that stand out) and let generations pass.',setup:()=>{loadScen('arctic');CL.temp=-4;syncClimateUI();const rb=[];for(const r of S.animals)if(r.sp==='rabbit'){rb.push(r);r.genes.coat=(rnd()<.35?'w':'N')+(rnd()<.35?'w':'N');r.col=colorOf('rabbit',r.genes)}for(let k=0;k<3&&rb.length;k++){const z=rb[Math.floor(rnd()*rb.length)];spawnAt('fox',z.x,z.y,2,true,0.9)}CH.ref.ge=GENEDIT},check:()=>{let n=0,w=0;for(const a of S.animals)if(!a.dead&&a.sp==='rabbit'){n++;if(coatOf(a.genes)==='white')w++}const f=n?w/n:0;return[f>=.35&&GENEDIT===CH.ref.ge,f/.35,`${Math.round(f*100)}% of ${n} rabbits are white`]},fail:()=>cnt('rabbit')?'':'The rabbits died out',stars:byTime(90,240)});
