let demoI=-1,demoTimer=0;
function startDemo(){leaveHome();countPlay();setMode('demo');$('demoCap').hidden=false;demoI=-1;nextDemo()}
function nextDemo(){clearTimeout(demoTimer);demoI=(demoI+1)%DEMO.length;const [id,t,x,f]=DEMO[demoI];CH.loading=true;loadScen(id);CH.loading=false;setPaused(false);f();
  $('demoStep').textContent=`Demo · ${demoI+1} of ${DEMO.length}`;$('demoTitle').textContent=t;$('demoText').textContent=x;demoTimer=setTimeout(nextDemo,12000)}
function stopDemo(quiet){clearTimeout(demoTimer);if(demoI<0&&quiet)return;demoI=-1;$('demoCap').hidden=true;setMode('');setView('normal');if(!quiet)showHome()}
$('hWatch').onclick=startDemo;$('demoExit').onclick=()=>stopDemo();$('demoNext').onclick=nextDemo;

/* ================= main loop ================= */
let last=performance.now(),uiT=0,achAcc=0,achT=0,renderMs=4,stepMs=1;
function frame(now){const dtR=Math.min(0.1,(now-last)/1000);last=now;camKeys(dtR);
  try{
  if(!S.paused){const want=S.speed*dtR,step=Math.min(S.speed>=180?1:0.5,Math.max(0.04,S.speed/55)),t0=performance.now();let done=0;
    // the simulation gets whatever time is left in a 60 fps frame after drawing
    const budget=clamp(12.5-renderMs,2.5,9);
    while(done<want-1e-9){const el=performance.now()-t0;if(el+stepMs*0.9>budget&&done>0)break;const s0=performance.now(),d=Math.min(step,want-done);simStep(d);done+=d;stepMs=stepMs*0.8+(performance.now()-s0)*0.2}
    if(done>0)updateVegSliced(done);achAcc+=done}
  achT+=dtR;if(achT>=0.5){S.achieved=achAcc/achT;achAcc=0;achT=0}
  if(S.falling){S.falling.t+=dtR*1.4;if(S.falling.t>=1){const f=S.falling;S.falling=null;meteor(f.x,f.y,12);EVN++}}
  if(S.flash){S.flash.t-=dtR*1.2;if(S.flash.t<=0)S.flash=null}
  for(const p of S.parts){p.x+=p.vx*dtR;p.y+=p.vy*dtR;p.life-=dtR}if(S.parts.length)S.parts=S.parts.filter(p=>p.life>0);if(S.parts.length>1500)S.parts.splice(0,S.parts.length-1500);
  if(S.follow&&S.sel&&!S.sel.dead){cam.x=lerp(cam.x,nX(S.sel.x)*CELL,Math.min(1,dtR*6));cam.y=lerp(cam.y,nY(S.sel.y)*CELL,Math.min(1,dtR*6))}
  const r0=performance.now();render(now);renderMs=renderMs*0.85+(performance.now()-r0)*0.15;
  uiT+=dtR;if(uiT>0.25){uiT=0;updateHud()}
  }catch(err){console.error('[Biosphere]',err)}
  requestAnimationFrame(frame)}
// endangered species: fewer than 15 alive. Extinct: was alive in this world, now gone.
const ENDANGERED=15;
function checkEndangered(c){const st=S.status||(S.status={});S.seen=S.seen||{};const msgs=[];
  for(const k of SPK){const n=c[k]||0;if(n>0)S.seen[k]=1;if(!S.seen[k])continue;const now=n===0?'extinct':n<ENDANGERED?'endangered':'ok',was=st[k];
    if(S.statusReady&&was&&was!==now){if(now==='extinct'){msgs.push(`✖ ${SP[k].pl} are extinct`);chEv('extinct',{sp:k})}else if(now==='endangered'&&was==='ok'){msgs.push(`⚠ ${SP[k].pl} are endangered: only ${n} left`);chEv('endangered',{sp:k})}else if(now==='ok'&&was!=='ok'){msgs.push(`✓ ${SP[k].pl} are safe again (${n})`);chEv('recovered',{sp:k})}}
    st[k]=now}
  S.statusReady=true;for(const m of msgs.slice(0,3))toast(m);
  const end=SPK.filter(k=>st[k]==='endangered'),ext=SPK.filter(k=>st[k]==='extinct'),b=$('endBadge');
  b.hidden=!end.length&&!ext.length;b.textContent=`⚠ ${end.length} endangered${ext.length?` · ✖ ${ext.length} extinct`:''}`}
function renderEndangered(c){const st=S.status||{},box=$('endBox'),end=SPK.filter(k=>st[k]==='endangered').sort((a,b)=>(c[a]||0)-(c[b]||0)),ext=SPK.filter(k=>st[k]==='extinct');box.hidden=!end.length&&!ext.length;if(box.hidden)return;
  box.textContent='';const h=document.createElement('span');h.className='k';h.textContent=`Endangered: fewer than ${ENDANGERED} left`;box.appendChild(h);
  for(const k of [...end,...ext]){const r=document.createElement('button');r.className='endrow'+(st[k]==='extinct'?' ext':'');r.innerHTML='<span></span><b></b>';r.children[0].textContent=`${SP[k].ic} ${SP[k].pl}`;r.children[1].textContent=st[k]==='extinct'?'extinct':c[k];r.onclick=()=>{if(c[k])flyTo(k)};box.appendChild(r)}}
$('endBadge').onclick=()=>{showTab('life');document.body.classList.add('dockOpen')};
function updateHud(){updateEventButtons();measureHud();const c=counts();let n=0,sp=0;for(const k of SPK){n+=c[k];if(c[k])sp++}$('nAnimals').textContent=n;{let sp=0;for(const t of S.trees)if(t.size<0.3)sp++;$('nTrees').textContent=sp?`${S.trees.length} (${sp} 🌱)`:S.trees.length}$('nSpecies').textContent=sp;
  $('dateTxt').textContent=dateTxt();const ci=idx(wxOf(W/2),wyOf(H/2));$('tempTxt').textContent=ci>=0?`${cellT(ci).toFixed(0)} °C at the centre${CL.dust>0.5?' · dusty sky':''}`:'';
  $('rateTxt').textContent=S.paused?'Paused':fmtRate(S.speed)+(S.achieved<S.speed*0.85&&S.speed>30?` (running ${fmtRate(Math.max(0.01,S.achieved))})`:'');
  checkEndangered(c);if(!$('pane-life').hidden)renderLife();updateInspector();chTick();
  if(document.visibilityState==='visible'&&$('home').hidden){PROG.secs=(PROG.secs||0)+0.25}}
addEventListener('resize',()=>{resize()});addEventListener('pagehide',saveProg);

